package com.bank.cleansing.service;

import com.bank.cleansing.model.Employee;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class DataCleansingService {
    private static final Logger log = Logger.getLogger(DataCleansingService.class.getName());

    public List<Employee> withValidNames(List<Employee> employees) {
        log.info(() -> "Cleansing " + employees.size() + " imported records");
        return employees.stream()
                // Null check FIRST (short-circuit), then non-blank after trim.
                .filter(e -> e.getName() != null && !e.getName().trim().isEmpty())
                .collect(Collectors.toList());
    }
}
