package com.bank.cleansing;

import com.bank.cleansing.model.Employee;
import com.bank.cleansing.service.DataCleansingService;
import java.util.Arrays;
import java.util.List;
import java.util.logging.Logger;

public class Main {
    private static final Logger log = Logger.getLogger(Main.class.getName());

    public static void main(String[] args) {
        List<Employee> imported = Arrays.asList(
            new Employee("E1", "Rajesh"),
            new Employee("E2", null),      // null name
            new Employee("E3", "   "),     // whitespace only
            new Employee("E4", "Priya"),
            new Employee("E5", "")          // empty string
        );

        List<Employee> clean = new DataCleansingService().withValidNames(imported);
        clean.forEach(e -> log.info(() -> "Clean record: " + e));
        log.info(() -> "Kept " + clean.size() + " of " + imported.size());
    }
}
